<template>
  <section class="financial-center">
    <div v-if="failed" class="wb-error">金融数据库读取失败。<el-button text @click="load">重新加载</el-button></div>
    <template v-if="overview">
      <div class="financial-stats"><div><span>金融交易明细</span><strong>{{ num(overview.stats.financialTransactions) }}</strong><small>银行流水与匿名信用卡交易</small></div><div><span>关联银行账户</span><strong>{{ num(overview.stats.accounts) }}</strong><small>{{ num(overview.stats.loans) }} 份贷款合同</small></div><div><span>国家与经济体</span><strong>{{ overview.stats.countries }}</strong><small>全球汇款年度统计覆盖</small></div><div><span>风险名单主体</span><strong>{{ num(overview.stats.sanctionEntities) }}</strong><small>OFAC官方名单快照</small></div></div>
      <div class="financial-catalog"><article v-for="s in overview.sources" :key="s.id"><div><span>{{ kindNames[s.kind] }}</span><h3>{{ s.title }}</h3><p>{{ s.geography }}</p></div><div class="financial-catalog-actions"><strong>{{ num(s.row_count) }}</strong><div><el-button link @click="useSource(s)">查看数据</el-button><el-button link @click="inspectSource(s.id)">来源与血缘</el-button></div></div></article></div>
      <el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane label="金融与订单明细" name="transactions"/><el-tab-pane label="账户关系" name="accounts"/><el-tab-pane label="多币种参考" name="fx"/><el-tab-pane label="全球汇款统计" name="macro"/><el-tab-pane label="名单筛查" name="screen"/><el-tab-pane label="数据结构" name="schema"/></el-tabs>
      <section v-if="tab==='transactions'">
        <div class="fs-toolbar"><el-select v-model="source" style="width:240px" @change="search"><el-option v-for="s in transactionSources" :key="s.id" :value="s.id" :label="s.title"/></el-select><el-input v-model="query" placeholder="交易编号或账户编号" clearable @keyup.enter="search" style="width:240px"/><el-select v-if="source==='ULB-1597'" v-model="label" clearable placeholder="全部公开标签" @change="search" style="width:170px"><el-option label="公开标签：欺诈" value="1"/><el-option label="公开标签：非欺诈" value="0"/></el-select><el-button @click="search">查询</el-button><span class="fs-muted">{{ num(total) }} 笔</span></div>
        <p class="financial-note">{{ selectedSource?.limitations }}</p>
        <el-table :data="rows" v-loading="loading" @row-click="inspectTransaction" row-class-name="wb-click-row"><el-table-column prop="id" label="来源编号" min-width="170"/><el-table-column prop="account_id" label="关联账户" min-width="150"/><el-table-column label="原始金额" min-width="145" align="right"><template #default="{row}">{{ row.amount_value }} {{ row.currency || '单位未确认' }}</template></el-table-column><el-table-column label="记录时间" min-width="180"><template #default="{row}">{{ row.occurred_at || (row.elapsed_seconds!==null?'相对 '+row.elapsed_seconds+' 秒':'未公开') }}</template></el-table-column><el-table-column prop="direction" label="借贷方向" width="115"/><el-table-column label="公开标签" width="120"><template #default="{row}">{{ row.observed_fraud_label===null?'未提供':row.observed_fraud_label===1?'欺诈':'非欺诈' }}</template></el-table-column></el-table>
        <el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="loadTransactions"/>
        <section v-if="source==='ULB-1597'" class="financial-model"><h3>真实欺诈标签基准验证</h3><template v-if="model?.status==='trained'"><div class="financial-stats"><div v-for="(value,key) in modelMetrics" :key="key"><span>{{ key }}</span><strong>{{ value }}</strong></div></div><p>训练 {{ num(model.split.train) }} · 独立校准 {{ num(model.split.calibration) }} · 时间留出测试 {{ num(model.split.test) }}；{{ model.thresholdMethod }}。</p><p>{{ model.limitations }}</p></template><p v-else>尚无完成的训练实测，不显示虚构性能。</p></section>
      </section>
      <section v-else-if="tab==='accounts'"><div class="fs-toolbar"><el-input v-model="accountId" placeholder="例如CTU-BERKA:1" style="width:300px" @keyup.enter="loadAccount"/><el-button @click="loadAccount">查看账户关系</el-button></div><template v-if="account"><h3>{{ account.id }} · {{ account.currency }} · {{ account.country }}</h3><div class="financial-relations"><article v-for="p in account.parties" :key="p.id"><strong>{{ p.display_name }}</strong><span>{{ p.rights }}</span></article><article><strong>账户 {{ account.source_key }}</strong><span>开户 {{ account.opened_on }}</span></article><article><strong>{{ account.loans.length }} 份贷款 · {{ account.standingOrders.length }} 项常设支付指令</strong><span>均由来源主外键关联</span></article></div><h3>近30个有记录日的账户汇总</h3><el-table :data="account.daily"><el-table-column prop="day" label="日期"/><el-table-column prop="transaction_count" label="交易笔数"/><el-table-column label="流入CZK"><template #default="{row}">{{ moneyMinor(row.inflow_minor) }}</template></el-table-column><el-table-column label="流出CZK"><template #default="{row}">{{ moneyMinor(row.outflow_minor) }}</template></el-table-column><el-table-column label="日内余额范围CZK"><template #default="{row}">{{ moneyMinor(row.min_balance_minor) }} — {{ moneyMinor(row.max_balance_minor) }}</template></el-table-column></el-table><h3>贷款合同</h3><el-table :data="account.loans"><el-table-column prop="id" label="合同"/><el-table-column label="金额CZK"><template #default="{row}">{{ moneyMinor(row.amount_minor) }}</template></el-table-column><el-table-column prop="start_date" label="日期"/><el-table-column prop="duration_months" label="月数"/><el-table-column prop="source_status" label="原始贷款状态"/></el-table></template></section>
      <section v-else-if="tab==='fx'"><div class="fs-toolbar"><el-date-picker v-model="conversion.date" value-format="YYYY-MM-DD" placeholder="历史日期"/><el-input-number v-model="conversion.amount" :min="0" :max="1000000000000"/><el-select v-model="conversion.from" style="width:110px"><el-option v-for="c in currencies" :key="c" :value="c" :label="c"/></el-select><span>到</span><el-select v-model="conversion.to" style="width:110px"><el-option v-for="c in currencies" :key="c" :value="c" :label="c"/></el-select><el-button @click="convert">参考折算</el-button></div><p v-if="converted" class="financial-result">{{ converted.amount }} {{ converted.from }} ≈ {{ converted.converted }} {{ converted.to }} · 汇率日期 {{ converted.date }}</p><p class="financial-note">ECB参考值用于分析，不是交易报价；仅使用指定日或此前7天同日可用汇率，不用未来值填历史空缺。</p><h3>最新已入库参考值 · {{ fx?.date }}</h3><el-table :data="fx?.items || []" height="480"><el-table-column prop="base_currency" label="基准"/><el-table-column prop="quote_currency" label="报价币种"/><el-table-column prop="rate" label="每EUR对应金额"/></el-table></section>
      <section v-else-if="tab==='macro'"><div class="fs-toolbar"><el-select v-model="macroYear" style="width:120px" @change="loadMacro"><el-option v-for="year in years" :key="year" :value="year" :label="String(year)"/></el-select><el-select v-model="macroIndicator" style="width:230px" @change="loadMacro"><el-option label="个人汇款收入（USD）" value="BX.TRF.PWKR.CD.DT"/><el-option label="个人汇款支出（USD）" value="BM.TRF.PWKR.CD.DT"/></el-select></div><p class="financial-note">国家/经济体年度总量，剔除区域汇总项；不是逐笔交易，也不能据此推断双边资金路径。缺失不填0。</p><el-table :data="macroRows" height="520"><el-table-column prop="country_iso3" label="国家代码" width="120"/><el-table-column prop="country_name" label="国家/经济体" min-width="200"/><el-table-column prop="region" label="世界银行区域" min-width="200"/><el-table-column label="年度金额USD" align="right" min-width="180"><template #default="{row}">{{ row.value===null?'缺失':num(row.value) }}</template></el-table-column></el-table></section>
      <section v-else-if="tab==='screen'"><div class="fs-toolbar"><el-input v-model="screenName" placeholder="主体名称或公开别名" style="width:360px" @keyup.enter="screen"/><el-button @click="screen">名单筛查</el-button></div><p class="financial-note">按规范化姓名或别名完全相等找候选。同名不代表同一人，无结果不代表无风险；不自动处置匿名交易。</p><template v-if="screened"><p>{{ screened.items.length }} 个候选</p><article v-for="s in screened.items" :key="s.id" class="financial-screen-result"><h3>{{ s.name }}</h3><p>{{ s.programs }} · {{ s.entity_type || '未分类' }}</p><p>来源编号 {{ s.original_id }}</p><p>公开别名：{{ s.aliases.map(a=>a.name).join('；') || '无' }}</p><p>地址国家：{{ [...new Set(s.addresses.map(a=>a.country))].join('；') || '未提供' }}</p><details><summary>公开备注</summary>{{ s.remarks }}</details></article></template></section>
      <section v-else-if="tab==='schema'"><h3>FedShield金融数据模型 · {{ overview.tables.length }} 张表</h3><div class="financial-relations"><article><strong>主体与账户</strong><span>parties → account_parties → accounts</span></article><article><strong>业务流水与标签</strong><span>accounts → transactions → transaction_labels</span></article><article><strong>来源与治理</strong><span>sources → source_files / field_lineage / quality_checks</span></article></div><p class="financial-note">原始快照、标准化业务表、分析汇总分别保存；源键带命名空间，不跨数据源拼接匿名身份。贷款、持卡和常设指令通过原账户关系关联。</p><div class="financial-schema"><button v-for="s in schemaRows" :key="s.table" @click="schemaDetail=s"><strong>{{ s.table }}</strong><span>{{ s.columns.length }} 列 · {{ s.foreignKeys.length }} 个外键</span></button></div><el-table v-if="schemaDetail" :data="schemaDetail.columns"><el-table-column prop="name" label="字段"/><el-table-column prop="type" label="SQL类型"/><el-table-column prop="pk" label="主键标识"/></el-table></section>
    </template>
    <el-drawer :model-value="!!detail" @close="detail=null;++detailEpoch" title="记录与关联依据" size="min(820px,95vw)" append-to-body><template v-if="detail"><h3>{{ detail.id }}</h3><dl class="wb-dl wb-dl--vertical"><div v-for="key in ['source_id','source_key','amount_value','currency','occurred_at','time_precision','elapsed_seconds','source_locator']" :key="key"><dt>{{ key }}</dt><dd>{{ detail[key]??'未提供' }}</dd></div></dl><template v-if="detail.account"><el-button @click="accountId=detail.account_id;tab='accounts';loadAccount();detail=null">查看关联账户与贷款</el-button></template><template v-if="detail.prediction"><h3>模型分值与分区</h3><p>{{ detail.prediction.partition }} · 分值 {{ Number(detail.prediction.model_score).toFixed(5) }} · {{ detail.prediction.decision==='manual_review'?'建议人工复核':'初筛通过' }}</p><p class="financial-note">公开标签是数据集真值；模型分值来自独立训练，两者分开显示。训练分区记录不作为测试效果证明。</p></template><h3>原始字段</h3><pre class="financial-json">{{ JSON.stringify(Object.keys(detail.raw).length?detail.raw:detail.features,null,2) }}</pre></template></el-drawer>
    <el-dialog :model-value="!!sourceDetail" @close="sourceDetail=null;++sourceEpoch" title="来源与数据血缘" width="min(1000px,94vw)" append-to-body><template v-if="sourceDetail"><h3>{{ sourceDetail.title }}</h3><a :href="sourceDetail.source_url" target="_blank" rel="noopener noreferrer">{{ sourceDetail.citation }}</a><p>{{ sourceDetail.license_note }}</p><p>{{ sourceDetail.limitations }}</p><el-table :data="sourceDetail.files"><el-table-column prop="filename" label="原始快照" min-width="180"/><el-table-column prop="sha256" label="SHA-256" min-width="380"/><el-table-column prop="bytes" label="字节数" width="120"/></el-table><h3>字段映射</h3><el-table :data="sourceDetail.lineage"><el-table-column prop="source_field" label="原字段" min-width="180"/><el-table-column prop="target_field" label="标准字段" min-width="180"/><el-table-column prop="transformation" label="处理规则" min-width="300"/></el-table><h3>质量检查</h3><el-table :data="sourceDetail.quality"><el-table-column prop="check_name" label="检查" min-width="160"/><el-table-column prop="affected_rows" label="涉及记录" width="120"/><el-table-column prop="detail" label="处理说明" min-width="320"/></el-table></template></el-dialog>
  </section>
</template>
<script setup>
import {computed,onMounted,ref,reactive,watch} from 'vue'
import {financeApi} from '@/api'
const overview=ref(null),failed=ref(false),loading=ref(false),tab=ref('transactions'),source=ref('CTU-BERKA'),query=ref(''),label=ref(''),rows=ref([]),page=ref(1),total=ref(0),detail=ref(null),sourceDetail=ref(null),model=ref(null),accountId=ref('CTU-BERKA:1'),account=ref(null),fx=ref(null),converted=ref(null),macroYear=ref(2024),macroIndicator=ref('BX.TRF.PWKR.CD.DT'),macroRows=ref([]),screenName=ref(''),screened=ref(null),schemaRows=ref([]),schemaDetail=ref(null)
let detailEpoch=0,sourceEpoch=0,queryEpoch=0,accountEpoch=0,macroEpoch=0,conversionEpoch=0,screenEpoch=0
const kindNames={bank:'银行账务',card:'信用卡支付',commerce:'电商场景',fx:'货币参考',macro:'全球宏观',risk:'风险名单'},years=Array.from({length:26},(_,i)=>2025-i)
const conversion=reactive({date:'',amount:100,from:'GBP',to:'USD'})
watch(conversion,()=>{++conversionEpoch;converted.value=null},{flush:'sync'})
watch(screenName,()=>{++screenEpoch;screened.value=null},{flush:'sync'})
watch(accountId,()=>{++accountEpoch;account.value=null},{flush:'sync'})
const transactionSources=computed(()=>overview.value?.sources.filter(s=>['bank','card','commerce'].includes(s.kind))||[])
const selectedSource=computed(()=>transactionSources.value.find(s=>s.id===source.value))
const currencies=computed(()=>['EUR',...new Set(fx.value?.items.map(r=>r.quote_currency)||[])])
const num=n=>Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2}),moneyMinor=n=>(Number(n)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const modelMetrics=computed(()=>model.value?.test?{'PR-AUC':model.value.test.prAuc.toFixed(4),'ROC-AUC':model.value.test.rocAuc.toFixed(4),'精确率':(100*model.value.test.precision).toFixed(2)+'%','召回率':(100*model.value.test.recall).toFixed(2)+'%'}:{})
async function load(){failed.value=false;try{overview.value=await financeApi.overview();await loadTransactions();model.value=await financeApi.model()}catch{failed.value=true}}
async function loadTransactions(){const ticket=++queryEpoch;rows.value=[];total.value=0;loading.value=true;try{const r=await financeApi.transactions({source:source.value,q:query.value,label:source.value==='ULB-1597'?label.value:'',page:page.value,size:20});if(ticket!==queryEpoch)return;rows.value=r.items;total.value=r.total}catch{}finally{if(ticket===queryEpoch)loading.value=false}}
function search(){page.value=1;loadTransactions()}
async function inspectTransaction(row){const ticket=++detailEpoch;try{const r=await financeApi.transaction(row.id);if(ticket===detailEpoch)detail.value=r}catch{}}
async function inspectSource(id){const ticket=++sourceEpoch;try{const r=await financeApi.source(id);if(ticket===sourceEpoch)sourceDetail.value=r}catch{}}
function useSource(s){if(['bank','card','commerce'].includes(s.kind)){source.value=s.id;label.value='';tab.value='transactions';search()}else{tab.value={fx:'fx',macro:'macro',risk:'screen'}[s.kind];changeTab()}}
async function loadAccount(){const ticket=++accountEpoch;account.value=null;try{const r=await financeApi.account(accountId.value.trim());if(ticket===accountEpoch)account.value=r}catch{}}
async function loadMacro(){const ticket=++macroEpoch;macroRows.value=[];try{const r=await financeApi.macro({year:macroYear.value,indicator:macroIndicator.value});if(ticket===macroEpoch)macroRows.value=r.items}catch{}}
async function convert(){const ticket=++conversionEpoch,payload={...conversion};converted.value=null;try{const result=await financeApi.convert(payload);if(ticket===conversionEpoch)converted.value=result}catch{}}
async function screen(){const ticket=++screenEpoch,name=screenName.value;screened.value=null;try{const result=await financeApi.screen(name);if(ticket===screenEpoch)screened.value=result}catch{}}
async function changeTab(){try{if(tab.value==='accounts')await loadAccount();if(tab.value==='fx'&&!fx.value){fx.value=await financeApi.fx();conversion.date=fx.value.date}if(tab.value==='macro')await loadMacro();if(tab.value==='schema')schemaRows.value=await financeApi.schema()}catch{}}
onMounted(load)
</script>
<style scoped>
.financial-center{min-width:0}.financial-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px;padding:24px 0 30px}.financial-stats>div{display:flex;flex-direction:column;gap:8px}.financial-stats span,.financial-stats small{font-size:12px;color:#63727e}.financial-stats strong{font-size:30px;line-height:1.2;font-weight:600;color:#203b52}.financial-catalog{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 32px;margin-bottom:28px}.financial-catalog article{display:flex;gap:16px;justify-content:space-between;padding:20px 0;border-top:1px solid #e3e8ed;min-width:0}.financial-catalog h3{font-size:16px;margin:6px 0}.financial-catalog p,.financial-catalog span,.financial-note{font-size:12px;color:#667883;line-height:1.7}.financial-catalog p{margin:0}.financial-catalog-actions{flex-shrink:0;text-align:right}.financial-catalog-actions strong{font-size:20px;font-weight:500}.financial-catalog-actions>div{margin-top:10px}.financial-model{margin-top:32px;padding:24px;background:#f5f7f9;border-radius:12px}.financial-model p{font-size:13px;line-height:1.7;color:#63727e}.financial-model .financial-stats{padding:16px 0}.financial-relations{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:24px 0}.financial-relations article{padding:20px;border:1px solid #e1e7ed;border-radius:10px;display:flex;flex-direction:column;gap:10px;overflow-wrap:anywhere}.financial-relations strong{font-size:14px}.financial-relations span{font-size:12px;color:#63727e}.financial-json{padding:16px;background:#f5f7f9;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:8px;font-size:12px;line-height:1.8}.financial-schema{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0}.financial-schema button{display:flex;flex-direction:column;align-items:start;gap:8px;padding:16px;background:#f5f7f9;border:1px solid transparent;border-radius:8px;cursor:pointer;overflow-wrap:anywhere;text-align:left}.financial-schema button:hover,.financial-schema button:focus-visible{border-color:#0071e3}.financial-schema span{color:#63727e;font-size:12px}.financial-screen-result{padding:20px 0;border-top:1px solid #e1e7ed}.financial-screen-result p,.financial-screen-result details{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.financial-result{font-size:20px;color:#203b52}@media(max-width:900px){.financial-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.financial-catalog{grid-template-columns:1fr}.financial-relations,.financial-schema{grid-template-columns:1fr}.financial-stats strong{font-size:25px}.financial-catalog-actions strong{font-size:18px}.fs-toolbar{flex-wrap:wrap}}
</style>
